-----------------------逻辑部分function WindwalkerSale_Chk(nNpcId,nItemId)	if not Sys_ChkFullTime(tWindwalkerSale_Data["ActivetyTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-2")		return	end	if not ((Get_UserProfession() >= 160) and (Get_UserProfession() <= 165)) then		LinkNpcGossipFunc_New(nNpcId,"2-3")		return		end		local nCost	local nGlobal = tWindwalkerSale_Data["Global"]["Id"]	local nData = Get_SysDynaGlobalData1(nGlobal)		if nData < tWindwalkerSale_Data["Global"]["Open"] then		nCost = tWindwalkerSale_Data["OldServerCost"][nItemId]	else		nCost = tWindwalkerSale_Data["NewServerCost"][nItemId] or tWindwalkerSale_Data["OldServerCost"][nItemId]		if not Task_ChkStcValue(tWindwalkerSale_Stc["EventType"],tWindwalkerSale_Stc["DataType"]["IsNew"],"==",1) then			--新服大于1转退出			LinkNpcGossipFunc_New(nNpcId,"2-4")			return					end	end	--天石不足	if Get_UserEMoney() < nCost then		tNpcGossip[nNpcId]["Text211"] = string.format(tWindwalkerSale_Text[nNpcId]["Text211"],Get_ItemtypeName(nItemId),nCost)		LinkNpcGossipFunc_New(nNpcId,"2-1")		return		end	--背包不足	if not User_CheckLeftSpace(1) then		LinkNpcGossipFunc_New(nNpcId,"2-2")		return			end	--二次确认	WindwalkerSale_Comfirm(nNpcId,nItemId,nCost)endfunction WindwalkerSale_Comfirm(nNpcId,nItemId,nCost)	tNpcGossip[nNpcId]["Text311"] = string.format(tWindwalkerSale_Text[nNpcId]["Text311"],nCost,Get_ItemtypeName(nItemId))	tNpcGossip[nNpcId]["OptionFunc311"] = "WindwalkerSale_Buy</N>"..nNpcId.."</N>"..nItemId	LinkNpcGossipFunc_New(nNpcId,"3-1")endfunction WindwalkerSale_Buy(nNpcId,nItemId)	if not Sys_ChkFullTime(tWindwalkerSale_Data["ActivetyTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-2")		return	end	if not ((Get_UserProfession() >= 160) and (Get_UserProfession() <= 165)) then		LinkNpcGossipFunc_New(nNpcId,"2-3")		return		end		local nCost	local nGlobal = tWindwalkerSale_Data["Global"]["Id"]	local nData = Get_SysDynaGlobalData1(nGlobal)		if nData < tWindwalkerSale_Data["Global"]["Open"] then		nCost = tWindwalkerSale_Data["OldServerCost"][nItemId]	else		nCost = tWindwalkerSale_Data["NewServerCost"][nItemId] or tWindwalkerSale_Data["OldServerCost"][nItemId]		if not Task_ChkStcValue(tWindwalkerSale_Stc["EventType"],tWindwalkerSale_Stc["DataType"]["IsNew"],"==",1) then			--新服大于1转退出			LinkNpcGossipFunc_New(nNpcId,"2-4")			return					end			end	--天石不足	if Get_UserEMoney() < nCost then		tNpcGossip[nNpcId]["Text211"] = string.format(tWindwalkerSale_Text[nNpcId]["Text211"],Get_ItemtypeName(nItemId),nCost)		LinkNpcGossipFunc_New(nNpcId,"2-1")		return		end	--背包不足	if not User_CheckLeftSpace(1) then		LinkNpcGossipFunc_New(nNpcId,"2-2")		return			end	if User_AddEMoney(-nCost) then		local nEvent = tWindwalkerSale_Stc["EventType"]		local nType =tWindwalkerSale_Stc["DataType"][nItemId]				-- Task_AddStatistic(nEvent,nType,1,1)		local tWindwalkerSale_Temp = {}		tWindwalkerSale_Temp["LogId"] = 12000598		tWindwalkerSale_Temp["RewardItem"] = {}		tWindwalkerSale_Temp["RewardItem"][1] = {}		tWindwalkerSale_Temp["RewardItem"][1]["Id"] = nItemId		tWindwalkerSale_Temp["RewardItem"][1]["Attr"] = "0 1"		RewardTemplate_UseItemAndMsg(tWindwalkerSale_Temp)		Sys_SaveActionFestivalLog(string.format(tWindwalkerSale_Log["ActionLog"],nCost,nItemId))		Sys_SaveEmoneyBuy(string.format(tWindwalkerSale_Log["EmoneyLog"][nItemId],nCost,nCost))	endend--------------------------------------------------------------------------------------NPC模板tNpcFace[4477] = 117tNpcFace[4478] = 119tNpcGossip[20167] = tNpcGossip[20167] or DefaultNpc:new{}tNpcGossip[20167]["OptionHidden"] = 1tNpcGossip[20167]["DialogueText"] = tWindwalkerSale_Text[20167]tNpcGossip[20168] = tNpcGossip[20168] or DefaultNpc:new{}tNpcGossip[20168]["OptionHidden"] = 1tNpcGossip[20168]["DialogueText"] = tWindwalkerSale_Text[20168]tNpcGossip[20169] = tNpcGossip[20169] or DefaultNpc:new{}tNpcGossip[20169]["OptionHidden"] = 1tNpcGossip[20169]["DialogueText"] = tWindwalkerSale_Text[20169]tNpc